 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"coding-basics","ordinal":1,"title":"Werte verändern","theory":"Eine Zuweisung ersetzt den gespeicherten Variablenwert. Anschließend verwenden alle späteren Ausdrücke den neuen Wert.","example":"punkte = 5\npunkte = punkte + 2\nprint(punkte)","example_note":"Die zweite Zuweisung liest 5 und speichert 7. Die Ausgabe ist 7.","task":"Erhöhe einen Punktestand zweimal und gib jeweils den neuen Wert aus.","q1":{"question":"Welche Aussage erklärt „Werte verändern“ richtig?","options":["Ein f-String verbindet feste Textteile mit Variablenwerten. Ausdrücke innerhalb geschweifter Klammern werden ausgewertet.","Eine Zuweisung ersetzt den gespeicherten Variablenwert. Anschließend verwenden alle späteren Ausdrücke den neuen Wert.","Ein Vergleich liefert True oder False. Das Ergebnis steuert später Verzweigungen."],"correct":1,"explanation":"Eine Zuweisung ersetzt den gespeicherten Variablenwert. Anschließend verwenden alle späteren Ausdrücke den neuen Wert."},"q2":{"question":"Was zeigt das Beispiel zu „Werte verändern“?","options":["Der Name Alex wird ohne sichtbare Klammern in den Text eingefügt.","Der Vergleich liefert False, weil 17 kleiner als 18 ist.","Die zweite Zuweisung liest 5 und speichert 7. Die Ausgabe ist 7."],"correct":2,"explanation":"Die zweite Zuweisung liest 5 und speichert 7. Die Ausgabe ist 7."}},{"course":"coding-basics","ordinal":2,"title":"Text zusammensetzen","theory":"Ein f-String verbindet feste Textteile mit Variablenwerten. Ausdrücke innerhalb geschweifter Klammern werden ausgewertet.","example":"name = \"Alex\"\nprint(f\"Hallo {name}!\")","example_note":"Der Name Alex wird ohne sichtbare Klammern in den Text eingefügt.","task":"Erstelle einen Begrüßungstext mit Namen und Punktestand.","q1":{"question":"Welche Aussage erklärt „Text zusammensetzen“ richtig?","options":["input liefert in Python zuerst immer Text. Um damit zu rechnen, musst du geeignete Eingaben in Zahlen umwandeln.","Das Zeichen = weist einen Wert zu; == prüft, ob zwei Werte gleich sind. Beide Operationen sind verschieden.","Ein f-String verbindet feste Textteile mit Variablenwerten. Ausdrücke innerhalb geschweifter Klammern werden ausgewertet."],"correct":2,"explanation":"Ein f-String verbindet feste Textteile mit Variablenwerten. Ausdrücke innerhalb geschweifter Klammern werden ausgewertet."},"q2":{"question":"Was zeigt das Beispiel zu „Text zusammensetzen“?","options":["Der Name Alex wird ohne sichtbare Klammern in den Text eingefügt.","int wandelt Ziffern in eine Zahl um und löst für ungültigen Text einen Fehler aus.","Zuerst wird 3 gespeichert, danach ergibt der Vergleich True."],"correct":0,"explanation":"Der Name Alex wird ohne sichtbare Klammern in den Text eingefügt."}},{"course":"coding-basics","ordinal":3,"title":"Eingaben lesen","theory":"input liefert in Python zuerst immer Text. Um damit zu rechnen, musst du geeignete Eingaben in Zahlen umwandeln.","example":"alter_text = input(\"Alter: \")\nalter = int(alter_text)","example_note":"int wandelt Ziffern in eine Zahl um und löst für ungültigen Text einen Fehler aus.","task":"Lies eine Alterseingabe und teste einmal Ziffern und einmal Buchstaben.","q1":{"question":"Welche Aussage erklärt „Eingaben lesen“ richtig?","options":["input liefert in Python zuerst immer Text. Um damit zu rechnen, musst du geeignete Eingaben in Zahlen umwandeln.","Ein Vergleich liefert True oder False. Das Ergebnis steuert später Verzweigungen.","range(1,4) erzeugt die Werte 1, 2 und 3. Die obere Grenze ist nicht enthalten."],"correct":0,"explanation":"input liefert in Python zuerst immer Text. Um damit zu rechnen, musst du geeignete Eingaben in Zahlen umwandeln."},"q2":{"question":"Was zeigt das Beispiel zu „Eingaben lesen“?","options":["Der Vergleich liefert False, weil 17 kleiner als 18 ist.","int wandelt Ziffern in eine Zahl um und löst für ungültigen Text einen Fehler aus.","Der Schleifenkörper wird dreimal mit wechselndem n ausgeführt."],"correct":1,"explanation":"int wandelt Ziffern in eine Zahl um und löst für ungültigen Text einen Fehler aus."}},{"course":"coding-basics","ordinal":4,"title":"Boolesche Bedingungen","theory":"Ein Vergleich liefert True oder False. Das Ergebnis steuert später Verzweigungen.","example":"alter = 17\nprint(alter >= 18)","example_note":"Der Vergleich liefert False, weil 17 kleiner als 18 ist.","task":"Prüfe je einen Wert unter und über der Grenze.","q1":{"question":"Welche Aussage erklärt „Boolesche Bedingungen“ richtig?","options":["Das Zeichen = weist einen Wert zu; == prüft, ob zwei Werte gleich sind. Beide Operationen sind verschieden.","Ein Vergleich liefert True oder False. Das Ergebnis steuert später Verzweigungen.","Der erste Index einer Python-Liste ist 0. Ein Index greift gezielt auf ein Element zu."],"correct":1,"explanation":"Ein Vergleich liefert True oder False. Das Ergebnis steuert später Verzweigungen."},"q2":{"question":"Was zeigt das Beispiel zu „Boolesche Bedingungen“?","options":["Zuerst wird 3 gespeichert, danach ergibt der Vergleich True.","Die Ausgabe rot stammt vom ersten Eintrag an Position 0.","Der Vergleich liefert False, weil 17 kleiner als 18 ist."],"correct":2,"explanation":"Der Vergleich liefert False, weil 17 kleiner als 18 ist."}},{"course":"coding-basics","ordinal":5,"title":"Zuweisung und Vergleich","theory":"Das Zeichen = weist einen Wert zu; == prüft, ob zwei Werte gleich sind. Beide Operationen sind verschieden.","example":"zahl = 3\nprint(zahl == 3)","example_note":"Zuerst wird 3 gespeichert, danach ergibt der Vergleich True.","task":"Schreibe eine Zuweisung und prüfe sie mit ==.","q1":{"question":"Welche Aussage erklärt „Zuweisung und Vergleich“ richtig?","options":["range(1,4) erzeugt die Werte 1, 2 und 3. Die obere Grenze ist nicht enthalten.","return liefert ein Ergebnis aus einer Funktion zurück. print zeigt lediglich einen Textwert an.","Das Zeichen = weist einen Wert zu; == prüft, ob zwei Werte gleich sind. Beide Operationen sind verschieden."],"correct":2,"explanation":"Das Zeichen = weist einen Wert zu; == prüft, ob zwei Werte gleich sind. Beide Operationen sind verschieden."},"q2":{"question":"Was zeigt das Beispiel zu „Zuweisung und Vergleich“?","options":["Zuerst wird 3 gespeichert, danach ergibt der Vergleich True.","Der Schleifenkörper wird dreimal mit wechselndem n ausgeführt.","Der Funktionsaufruf liefert die Zahl 8; print macht sie sichtbar."],"correct":0,"explanation":"Zuerst wird 3 gespeichert, danach ergibt der Vergleich True."}},{"course":"coding-basics","ordinal":6,"title":"Schleifen zählen","theory":"range(1,4) erzeugt die Werte 1, 2 und 3. Die obere Grenze ist nicht enthalten.","example":"for n in range(1,4):\n    print(n)","example_note":"Der Schleifenkörper wird dreimal mit wechselndem n ausgeführt.","task":"Gib per Schleife die Zahlen 1 bis 5 aus.","q1":{"question":"Welche Aussage erklärt „Schleifen zählen“ richtig?","options":["range(1,4) erzeugt die Werte 1, 2 und 3. Die obere Grenze ist nicht enthalten.","Der erste Index einer Python-Liste ist 0. Ein Index greift gezielt auf ein Element zu.","try und except behandeln vorhersehbare Ausnahmen, ohne dass das ganze Programm unerwartet endet."],"correct":0,"explanation":"range(1,4) erzeugt die Werte 1, 2 und 3. Die obere Grenze ist nicht enthalten."},"q2":{"question":"Was zeigt das Beispiel zu „Schleifen zählen“?","options":["Die Ausgabe rot stammt vom ersten Eintrag an Position 0.","Der Schleifenkörper wird dreimal mit wechselndem n ausgeführt.","Die Umwandlung scheitert und ValueError wird abgefangen."],"correct":1,"explanation":"Der Schleifenkörper wird dreimal mit wechselndem n ausgeführt."}},{"course":"coding-basics","ordinal":7,"title":"Listenindizes","theory":"Der erste Index einer Python-Liste ist 0. Ein Index greift gezielt auf ein Element zu.","example":"farben = [\"rot\",\"blau\"]\nprint(farben[0])","example_note":"Die Ausgabe rot stammt vom ersten Eintrag an Position 0.","task":"Erstelle drei Farben und gib gezielt die letzte aus.","q1":{"question":"Welche Aussage erklärt „Listenindizes“ richtig?","options":["return liefert ein Ergebnis aus einer Funktion zurück. print zeigt lediglich einen Textwert an.","Der erste Index einer Python-Liste ist 0. Ein Index greift gezielt auf ein Element zu.","Quellcode und gespeicherte Daten gehören in unterschiedliche Dateien. So kann ein Programm Daten ändern, ohne den Code umzuschreiben."],"correct":1,"explanation":"Der erste Index einer Python-Liste ist 0. Ein Index greift gezielt auf ein Element zu."},"q2":{"question":"Was zeigt das Beispiel zu „Listenindizes“?","options":["Der Funktionsaufruf liefert die Zahl 8; print macht sie sichtbar.","Die .py-Datei ist Quellcode; eine separate JSON-Datei könnte später Inhalte speichern.","Die Ausgabe rot stammt vom ersten Eintrag an Position 0."],"correct":2,"explanation":"Die Ausgabe rot stammt vom ersten Eintrag an Position 0."}},{"course":"coding-basics","ordinal":8,"title":"Rückgabewerte","theory":"return liefert ein Ergebnis aus einer Funktion zurück. print zeigt lediglich einen Textwert an.","example":"def doppelt(x):\n    return x * 2\nprint(doppelt(4))","example_note":"Der Funktionsaufruf liefert die Zahl 8; print macht sie sichtbar.","task":"Schreibe eine Funktion, die eine Zahl verdreifacht.","q1":{"question":"Welche Aussage erklärt „Rückgabewerte“ richtig?","options":["try und except behandeln vorhersehbare Ausnahmen, ohne dass das ganze Programm unerwartet endet.","Ein Test vergleicht das erwartete mit dem tatsächlichen Ergebnis einer Funktion.","return liefert ein Ergebnis aus einer Funktion zurück. print zeigt lediglich einen Textwert an."],"correct":2,"explanation":"return liefert ein Ergebnis aus einer Funktion zurück. print zeigt lediglich einen Textwert an."},"q2":{"question":"Was zeigt das Beispiel zu „Rückgabewerte“?","options":["Der Funktionsaufruf liefert die Zahl 8; print macht sie sichtbar.","Die Umwandlung scheitert und ValueError wird abgefangen.","assert meldet eine Abweichung, wenn das berechnete Ergebnis nicht 9 ist."],"correct":0,"explanation":"Der Funktionsaufruf liefert die Zahl 8; print macht sie sichtbar."}},{"course":"coding-basics","ordinal":9,"title":"Fehler abfangen","theory":"try und except behandeln vorhersehbare Ausnahmen, ohne dass das ganze Programm unerwartet endet.","example":"try:\n    zahl = int(\"abc\")\nexcept ValueError:\n    print(\"Keine Zahl\")","example_note":"Die Umwandlung scheitert und ValueError wird abgefangen.","task":"Teste eine gültige und eine ungültige Zahleneingabe.","q1":{"question":"Welche Aussage erklärt „Fehler abfangen“ richtig?","options":["try und except behandeln vorhersehbare Ausnahmen, ohne dass das ganze Programm unerwartet endet.","Quellcode und gespeicherte Daten gehören in unterschiedliche Dateien. So kann ein Programm Daten ändern, ohne den Code umzuschreiben.","Ein Einstiegspunkt steuert, wann ein Skript beim direkten Start ausgeführt wird."],"correct":0,"explanation":"try und except behandeln vorhersehbare Ausnahmen, ohne dass das ganze Programm unerwartet endet."},"q2":{"question":"Was zeigt das Beispiel zu „Fehler abfangen“?","options":["Die .py-Datei ist Quellcode; eine separate JSON-Datei könnte später Inhalte speichern.","Die Umwandlung scheitert und ValueError wird abgefangen.","Beim direkten Start der Datei wird start aufgerufen; beim Import nicht automatisch."],"correct":1,"explanation":"Die Umwandlung scheitert und ValueError wird abgefangen."}},{"course":"coding-basics","ordinal":10,"title":"Dateien trennen","theory":"Quellcode und gespeicherte Daten gehören in unterschiedliche Dateien. So kann ein Programm Daten ändern, ohne den Code umzuschreiben.","example":"# Datei: main.py\nprint(\"Start\")","example_note":"Die .py-Datei ist Quellcode; eine separate JSON-Datei könnte später Inhalte speichern.","task":"Lege je eine Datei für Programm und Daten an.","q1":{"question":"Welche Aussage erklärt „Dateien trennen“ richtig?","options":["Ein Test vergleicht das erwartete mit dem tatsächlichen Ergebnis einer Funktion.","Quellcode und gespeicherte Daten gehören in unterschiedliche Dateien. So kann ein Programm Daten ändern, ohne den Code umzuschreiben.","Eine Zuweisung ersetzt den gespeicherten Variablenwert. Anschließend verwenden alle späteren Ausdrücke den neuen Wert."],"correct":1,"explanation":"Quellcode und gespeicherte Daten gehören in unterschiedliche Dateien. So kann ein Programm Daten ändern, ohne den Code umzuschreiben."},"q2":{"question":"Was zeigt das Beispiel zu „Dateien trennen“?","options":["assert meldet eine Abweichung, wenn das berechnete Ergebnis nicht 9 ist.","Die zweite Zuweisung liest 5 und speichert 7. Die Ausgabe ist 7.","Die .py-Datei ist Quellcode; eine separate JSON-Datei könnte später Inhalte speichern."],"correct":2,"explanation":"Die .py-Datei ist Quellcode; eine separate JSON-Datei könnte später Inhalte speichern."}},{"course":"coding-basics","ordinal":11,"title":"Funktionen testen","theory":"Ein Test vergleicht das erwartete mit dem tatsächlichen Ergebnis einer Funktion.","example":"def quadrat(x): return x*x\nassert quadrat(3) == 9","example_note":"assert meldet eine Abweichung, wenn das berechnete Ergebnis nicht 9 ist.","task":"Ergänze einen Test für 0 und negative Zahlen.","q1":{"question":"Welche Aussage erklärt „Funktionen testen“ richtig?","options":["Ein Einstiegspunkt steuert, wann ein Skript beim direkten Start ausgeführt wird.","Ein f-String verbindet feste Textteile mit Variablenwerten. Ausdrücke innerhalb geschweifter Klammern werden ausgewertet.","Ein Test vergleicht das erwartete mit dem tatsächlichen Ergebnis einer Funktion."],"correct":2,"explanation":"Ein Test vergleicht das erwartete mit dem tatsächlichen Ergebnis einer Funktion."},"q2":{"question":"Was zeigt das Beispiel zu „Funktionen testen“?","options":["assert meldet eine Abweichung, wenn das berechnete Ergebnis nicht 9 ist.","Beim direkten Start der Datei wird start aufgerufen; beim Import nicht automatisch.","Der Name Alex wird ohne sichtbare Klammern in den Text eingefügt."],"correct":0,"explanation":"assert meldet eine Abweichung, wenn das berechnete Ergebnis nicht 9 ist."}},{"course":"coding-basics","ordinal":12,"title":"Programme starten","theory":"Ein Einstiegspunkt steuert, wann ein Skript beim direkten Start ausgeführt wird.","example":"def start():\n    print(\"Willkommen\")\nif __name__ == \"__main__\":\n    start()","example_note":"Beim direkten Start der Datei wird start aufgerufen; beim Import nicht automatisch.","task":"Erstelle eine eigene Startfunktion mit Einstiegspunkt.","q1":{"question":"Welche Aussage erklärt „Programme starten“ richtig?","options":["Ein Einstiegspunkt steuert, wann ein Skript beim direkten Start ausgeführt wird.","Eine Zuweisung ersetzt den gespeicherten Variablenwert. Anschließend verwenden alle späteren Ausdrücke den neuen Wert.","input liefert in Python zuerst immer Text. Um damit zu rechnen, musst du geeignete Eingaben in Zahlen umwandeln."],"correct":0,"explanation":"Ein Einstiegspunkt steuert, wann ein Skript beim direkten Start ausgeführt wird."},"q2":{"question":"Was zeigt das Beispiel zu „Programme starten“?","options":["Die zweite Zuweisung liest 5 und speichert 7. Die Ausgabe ist 7.","Beim direkten Start der Datei wird start aufgerufen; beim Import nicht automatisch.","int wandelt Ziffern in eine Zahl um und löst für ungültigen Text einen Fehler aus."],"correct":1,"explanation":"Beim direkten Start der Datei wird start aufgerufen; beim Import nicht automatisch."}},{"course":"lua","ordinal":1,"title":"Funktionen als Werte","theory":"Eine Lua-Funktion kann wie andere Werte in einer Variable gespeichert und danach aufgerufen werden.","example":"local melden = function(text)\n    print(text)\nend\nmelden(\"Hallo\")","example_note":"melden ist eine Variable, deren Wert eine Funktion ist.","task":"Speichere eine Funktion in einer Variablen und rufe sie auf.","q1":{"question":"Welche Aussage erklärt „Funktionen als Werte“ richtig?","options":["Ein Lua-return kann mehrere Werte übergeben, die beim Aufruf auf mehrere Variablen verteilt werden.","Eine Lua-Funktion kann wie andere Werte in einer Variable gespeichert und danach aufgerufen werden.","Eine flache Kopie überträgt direkte Felder in eine neue Tabelle. Innere Tabellen werden dabei noch geteilt."],"correct":1,"explanation":"Eine Lua-Funktion kann wie andere Werte in einer Variable gespeichert und danach aufgerufen werden."},"q2":{"question":"Was zeigt das Beispiel zu „Funktionen als Werte“?","options":["q erhält den Quotienten und r den Divisionsrest.","Jedes direkte Feld wird übernommen; die neue Tabelle ist eine andere Referenz.","melden ist eine Variable, deren Wert eine Funktion ist."],"correct":2,"explanation":"melden ist eine Variable, deren Wert eine Funktion ist."}},{"course":"lua","ordinal":2,"title":"Mehrere Rückgaben","theory":"Ein Lua-return kann mehrere Werte übergeben, die beim Aufruf auf mehrere Variablen verteilt werden.","example":"local function teile(a,b)\n return a/b, a%b\nend\nlocal q,r=teile(7,3)","example_note":"q erhält den Quotienten und r den Divisionsrest.","task":"Gib aus einer Funktion Summe und Differenz zurück.","q1":{"question":"Welche Aussage erklärt „Mehrere Rückgaben“ richtig?","options":["Tabellen werden bei einer einfachen Zuweisung nicht kopiert. Zwei Variablen können dieselbe Tabelle meinen.","table.sort ordnet Arraywerte direkt in der vorhandenen Tabelle. Eine eigene Vergleichsfunktion steuert die Reihenfolge.","Ein Lua-return kann mehrere Werte übergeben, die beim Aufruf auf mehrere Variablen verteilt werden."],"correct":2,"explanation":"Ein Lua-return kann mehrere Werte übergeben, die beim Aufruf auf mehrere Variablen verteilt werden."},"q2":{"question":"Was zeigt das Beispiel zu „Mehrere Rückgaben“?","options":["q erhält den Quotienten und r den Divisionsrest.","Die Änderung über b ist auch über a sichtbar; es wird 9 ausgegeben.","Nach dem Sortieren steht 1 an Index 1."],"correct":0,"explanation":"q erhält den Quotienten und r den Divisionsrest."}},{"course":"lua","ordinal":3,"title":"Tabellenreferenzen","theory":"Tabellen werden bei einer einfachen Zuweisung nicht kopiert. Zwei Variablen können dieselbe Tabelle meinen.","example":"local a={punkte=5}\nlocal b=a\nb.punkte=9\nprint(a.punkte)","example_note":"Die Änderung über b ist auch über a sichtbar; es wird 9 ausgegeben.","task":"Zeige mit zwei Variablen eine gemeinsame Referenz.","q1":{"question":"Welche Aussage erklärt „Tabellenreferenzen“ richtig?","options":["Tabellen werden bei einer einfachen Zuweisung nicht kopiert. Zwei Variablen können dieselbe Tabelle meinen.","Eine flache Kopie überträgt direkte Felder in eine neue Tabelle. Innere Tabellen werden dabei noch geteilt.","Lua-Muster beschreiben Textformen: %d steht für eine Ziffer und + für eine oder mehrere Wiederholungen."],"correct":0,"explanation":"Tabellen werden bei einer einfachen Zuweisung nicht kopiert. Zwei Variablen können dieselbe Tabelle meinen."},"q2":{"question":"Was zeigt das Beispiel zu „Tabellenreferenzen“?","options":["Jedes direkte Feld wird übernommen; die neue Tabelle ist eine andere Referenz.","Die Änderung über b ist auch über a sichtbar; es wird 9 ausgegeben.","nummer wird zum Text 42, weil er dem Suchmuster entspricht."],"correct":1,"explanation":"Die Änderung über b ist auch über a sichtbar; es wird 9 ausgegeben."}},{"course":"lua","ordinal":4,"title":"Tabellen flach kopieren","theory":"Eine flache Kopie überträgt direkte Felder in eine neue Tabelle. Innere Tabellen werden dabei noch geteilt.","example":"local neu={}\nfor k,v in pairs(alt) do neu[k]=v end","example_note":"Jedes direkte Feld wird übernommen; die neue Tabelle ist eine andere Referenz.","task":"Erstelle eine flache Kopie und ändere ein Feld.","q1":{"question":"Welche Aussage erklärt „Tabellen flach kopieren“ richtig?","options":["table.sort ordnet Arraywerte direkt in der vorhandenen Tabelle. Eine eigene Vergleichsfunktion steuert die Reihenfolge.","Eine flache Kopie überträgt direkte Felder in eine neue Tabelle. Innere Tabellen werden dabei noch geteilt.","__index bestimmt, wo Lua einen fehlenden Tabellenschlüssel nachschlägt. So entstehen Standardwerte."],"correct":1,"explanation":"Eine flache Kopie überträgt direkte Felder in eine neue Tabelle. Innere Tabellen werden dabei noch geteilt."},"q2":{"question":"Was zeigt das Beispiel zu „Tabellen flach kopieren“?","options":["Nach dem Sortieren steht 1 an Index 1.","t.farbe ergibt rot, obwohl t selbst keinen Farbeintrag hat.","Jedes direkte Feld wird übernommen; die neue Tabelle ist eine andere Referenz."],"correct":2,"explanation":"Jedes direkte Feld wird übernommen; die neue Tabelle ist eine andere Referenz."}},{"course":"lua","ordinal":5,"title":"Listen sortieren","theory":"table.sort ordnet Arraywerte direkt in der vorhandenen Tabelle. Eine eigene Vergleichsfunktion steuert die Reihenfolge.","example":"local z={4,1,3}\ntable.sort(z)\nprint(z[1])","example_note":"Nach dem Sortieren steht 1 an Index 1.","task":"Sortiere drei Preise absteigend.","q1":{"question":"Welche Aussage erklärt „Listen sortieren“ richtig?","options":["Lua-Muster beschreiben Textformen: %d steht für eine Ziffer und + für eine oder mehrere Wiederholungen.","Die Doppelpunkt-Schreibweise übergibt das Objekt als self an die Methode.","table.sort ordnet Arraywerte direkt in der vorhandenen Tabelle. Eine eigene Vergleichsfunktion steuert die Reihenfolge."],"correct":2,"explanation":"table.sort ordnet Arraywerte direkt in der vorhandenen Tabelle. Eine eigene Vergleichsfunktion steuert die Reihenfolge."},"q2":{"question":"Was zeigt das Beispiel zu „Listen sortieren“?","options":["Nach dem Sortieren steht 1 an Index 1.","nummer wird zum Text 42, weil er dem Suchmuster entspricht.","Der Aufruf p:gruss() liest den Namen aus p."],"correct":0,"explanation":"Nach dem Sortieren steht 1 an Index 1."}},{"course":"lua","ordinal":6,"title":"Muster mit string.match","theory":"Lua-Muster beschreiben Textformen: %d steht für eine Ziffer und + für eine oder mehrere Wiederholungen.","example":"local nummer=string.match(\"item42\",\"%d+\")","example_note":"nummer wird zum Text 42, weil er dem Suchmuster entspricht.","task":"Extrahiere die Ziffern aus einem anderen Text.","q1":{"question":"Welche Aussage erklärt „Muster mit string.match“ richtig?","options":["Lua-Muster beschreiben Textformen: %d steht für eine Ziffer und + für eine oder mehrere Wiederholungen.","__index bestimmt, wo Lua einen fehlenden Tabellenschlüssel nachschlägt. So entstehen Standardwerte.","Mit coroutine.yield kann eine Coroutine anhalten und mit coroutine.resume später fortgesetzt werden."],"correct":0,"explanation":"Lua-Muster beschreiben Textformen: %d steht für eine Ziffer und + für eine oder mehrere Wiederholungen."},"q2":{"question":"Was zeigt das Beispiel zu „Muster mit string.match“?","options":["t.farbe ergibt rot, obwohl t selbst keinen Farbeintrag hat.","nummer wird zum Text 42, weil er dem Suchmuster entspricht.","Der erste resume-Aufruf liefert Pause, der nächste kann Fertig liefern."],"correct":1,"explanation":"nummer wird zum Text 42, weil er dem Suchmuster entspricht."}},{"course":"lua","ordinal":7,"title":"Metatable __index","theory":"__index bestimmt, wo Lua einen fehlenden Tabellenschlüssel nachschlägt. So entstehen Standardwerte.","example":"local defaults={farbe=\"rot\"}\nlocal t=setmetatable({},{__index=defaults})","example_note":"t.farbe ergibt rot, obwohl t selbst keinen Farbeintrag hat.","task":"Hinterlege einen Standardwert für fehlende Konfiguration.","q1":{"question":"Welche Aussage erklärt „Metatable __index“ richtig?","options":["Die Doppelpunkt-Schreibweise übergibt das Objekt als self an die Methode.","__index bestimmt, wo Lua einen fehlenden Tabellenschlüssel nachschlägt. So entstehen Standardwerte.","Eine innere Funktion merkt sich lokale Variablen ihrer äußeren Funktion über deren Aufruf hinaus."],"correct":1,"explanation":"__index bestimmt, wo Lua einen fehlenden Tabellenschlüssel nachschlägt. So entstehen Standardwerte."},"q2":{"question":"Was zeigt das Beispiel zu „Metatable __index“?","options":["Der Aufruf p:gruss() liest den Namen aus p.","Die zurückgegebene Funktion kann n dauerhaft erhöhen.","t.farbe ergibt rot, obwohl t selbst keinen Farbeintrag hat."],"correct":2,"explanation":"t.farbe ergibt rot, obwohl t selbst keinen Farbeintrag hat."}},{"course":"lua","ordinal":8,"title":"Methoden mit self","theory":"Die Doppelpunkt-Schreibweise übergibt das Objekt als self an die Methode.","example":"local p={name=\"Alex\"}\nfunction p:gruss() return \"Hallo \"..self.name end","example_note":"Der Aufruf p:gruss() liest den Namen aus p.","task":"Schreibe eine Methode, die einen Punktestand zurückgibt.","q1":{"question":"Welche Aussage erklärt „Methoden mit self“ richtig?","options":["Mit coroutine.yield kann eine Coroutine anhalten und mit coroutine.resume später fortgesetzt werden.","error löst einen Laufzeitfehler aus, pcall fängt ihn geschützt auf und meldet Erfolg oder Fehler.","Die Doppelpunkt-Schreibweise übergibt das Objekt als self an die Methode."],"correct":2,"explanation":"Die Doppelpunkt-Schreibweise übergibt das Objekt als self an die Methode."},"q2":{"question":"Was zeigt das Beispiel zu „Methoden mit self“?","options":["Der Aufruf p:gruss() liest den Namen aus p.","Der erste resume-Aufruf liefert Pause, der nächste kann Fertig liefern.","ok wird false, err enthält eine Fehlermeldung."],"correct":0,"explanation":"Der Aufruf p:gruss() liest den Namen aus p."}},{"course":"lua","ordinal":9,"title":"Coroutines","theory":"Mit coroutine.yield kann eine Coroutine anhalten und mit coroutine.resume später fortgesetzt werden.","example":"local co=coroutine.create(function()\n coroutine.yield(\"Pause\")\n return \"Fertig\"\nend)","example_note":"Der erste resume-Aufruf liefert Pause, der nächste kann Fertig liefern.","task":"Starte eine Coroutine schrittweise.","q1":{"question":"Welche Aussage erklärt „Coroutines“ richtig?","options":["Mit coroutine.yield kann eine Coroutine anhalten und mit coroutine.resume später fortgesetzt werden.","Eine innere Funktion merkt sich lokale Variablen ihrer äußeren Funktion über deren Aufruf hinaus.","type zeigt den Lua-Datentyp eines Wertes an. Vor Rechnungen sollte ein unbekannter Wert geprüft werden."],"correct":0,"explanation":"Mit coroutine.yield kann eine Coroutine anhalten und mit coroutine.resume später fortgesetzt werden."},"q2":{"question":"Was zeigt das Beispiel zu „Coroutines“?","options":["Die zurückgegebene Funktion kann n dauerhaft erhöhen.","Der erste resume-Aufruf liefert Pause, der nächste kann Fertig liefern.","Die Funktion akzeptiert nur nichtnegative Zahlen."],"correct":1,"explanation":"Der erste resume-Aufruf liefert Pause, der nächste kann Fertig liefern."}},{"course":"lua","ordinal":10,"title":"Closures","theory":"Eine innere Funktion merkt sich lokale Variablen ihrer äußeren Funktion über deren Aufruf hinaus.","example":"local function zaehler()\n local n=0\n return function() n=n+1; return n end\nend","example_note":"Die zurückgegebene Funktion kann n dauerhaft erhöhen.","task":"Erzeuge zwei unabhängige Zähler.","q1":{"question":"Welche Aussage erklärt „Closures“ richtig?","options":["error löst einen Laufzeitfehler aus, pcall fängt ihn geschützt auf und meldet Erfolg oder Fehler.","Eine innere Funktion merkt sich lokale Variablen ihrer äußeren Funktion über deren Aufruf hinaus.","Benannte Tabellenschlüssel ermöglichen direkten Zugriff auf zugeordnete Werte."],"correct":1,"explanation":"Eine innere Funktion merkt sich lokale Variablen ihrer äußeren Funktion über deren Aufruf hinaus."},"q2":{"question":"Was zeigt das Beispiel zu „Closures“?","options":["ok wird false, err enthält eine Fehlermeldung.","Die Anfrage sucht den Schlüssel wasser und liefert den Wert 10.","Die zurückgegebene Funktion kann n dauerhaft erhöhen."],"correct":2,"explanation":"Die zurückgegebene Funktion kann n dauerhaft erhöhen."}},{"course":"lua","ordinal":11,"title":"error und pcall","theory":"error löst einen Laufzeitfehler aus, pcall fängt ihn geschützt auf und meldet Erfolg oder Fehler.","example":"local ok,err=pcall(function() error(\"ungültig\") end)","example_note":"ok wird false, err enthält eine Fehlermeldung.","task":"Fange einen selbst erzeugten Fehler ab.","q1":{"question":"Welche Aussage erklärt „error und pcall“ richtig?","options":["type zeigt den Lua-Datentyp eines Wertes an. Vor Rechnungen sollte ein unbekannter Wert geprüft werden.","Clientdaten sind manipulierbar. Ein FiveM-Serverhandler muss seine Argumente vor geschützten Aktionen prüfen.","error löst einen Laufzeitfehler aus, pcall fängt ihn geschützt auf und meldet Erfolg oder Fehler."],"correct":2,"explanation":"error löst einen Laufzeitfehler aus, pcall fängt ihn geschützt auf und meldet Erfolg oder Fehler."},"q2":{"question":"Was zeigt das Beispiel zu „error und pcall“?","options":["ok wird false, err enthält eine Fehlermeldung.","Die Funktion akzeptiert nur nichtnegative Zahlen.","Bei anderen Typen beendet sich der Handler; weitere Preisprüfungen bleiben nötig."],"correct":0,"explanation":"ok wird false, err enthält eine Fehlermeldung."}},{"course":"lua","ordinal":12,"title":"Typen prüfen","theory":"type zeigt den Lua-Datentyp eines Wertes an. Vor Rechnungen sollte ein unbekannter Wert geprüft werden.","example":"local function ok(x)\n return type(x)==\"number\" and x>=0\nend","example_note":"Die Funktion akzeptiert nur nichtnegative Zahlen.","task":"Prüfe Text, eine negative Zahl und eine gültige Zahl.","q1":{"question":"Welche Aussage erklärt „Typen prüfen“ richtig?","options":["type zeigt den Lua-Datentyp eines Wertes an. Vor Rechnungen sollte ein unbekannter Wert geprüft werden.","Benannte Tabellenschlüssel ermöglichen direkten Zugriff auf zugeordnete Werte.","Fachliche Prüfungen können als lokale Funktionen unabhängig vom Netzwerkereignis getestet werden."],"correct":0,"explanation":"type zeigt den Lua-Datentyp eines Wertes an. Vor Rechnungen sollte ein unbekannter Wert geprüft werden."},"q2":{"question":"Was zeigt das Beispiel zu „Typen prüfen“?","options":["Die Anfrage sucht den Schlüssel wasser und liefert den Wert 10.","Die Funktion akzeptiert nur nichtnegative Zahlen.","Die Funktion prüft nur zwei Argumente und kann separat aufgerufen werden."],"correct":1,"explanation":"Die Funktion akzeptiert nur nichtnegative Zahlen."}},{"course":"lua","ordinal":13,"title":"Key-Value-Lookup","theory":"Benannte Tabellenschlüssel ermöglichen direkten Zugriff auf zugeordnete Werte.","example":"local preise={brot=25,wasser=10}\nprint(preise[\"wasser\"])","example_note":"Die Anfrage sucht den Schlüssel wasser und liefert den Wert 10.","task":"Lege drei Artikelpreise in einer Lookup-Tabelle ab.","q1":{"question":"Welche Aussage erklärt „Key-Value-Lookup“ richtig?","options":["Clientdaten sind manipulierbar. Ein FiveM-Serverhandler muss seine Argumente vor geschützten Aktionen prüfen.","Benannte Tabellenschlüssel ermöglichen direkten Zugriff auf zugeordnete Werte.","Ein Cooldown verhindert zu häufige Aktionen, indem der Server die Zeit der letzten Aktion speichert."],"correct":1,"explanation":"Benannte Tabellenschlüssel ermöglichen direkten Zugriff auf zugeordnete Werte."},"q2":{"question":"Was zeigt das Beispiel zu „Key-Value-Lookup“?","options":["Bei anderen Typen beendet sich der Handler; weitere Preisprüfungen bleiben nötig.","Erst nach fünf Sekunden wird die nächste Aktion angenommen.","Die Anfrage sucht den Schlüssel wasser und liefert den Wert 10."],"correct":2,"explanation":"Die Anfrage sucht den Schlüssel wasser und liefert den Wert 10."}},{"course":"lua","ordinal":14,"title":"Server-Events validieren","theory":"Clientdaten sind manipulierbar. Ein FiveM-Serverhandler muss seine Argumente vor geschützten Aktionen prüfen.","example":"RegisterNetEvent(\"shop:buy\",function(item)\n if type(item)~=\"string\" then return end\nend)","example_note":"Bei anderen Typen beendet sich der Handler; weitere Preisprüfungen bleiben nötig.","task"